224	    // 设置使用的AI Core数量
225	    context->SetBlockDim(usedCoreNum);
226	
227	    // 根据数据类型设置tiling key
228	    uint64_t tilingKey = 0;
229	    if (dataType == ge::DT_FLOAT) {
230	        // 浮点数类型使用mode 0的tiling key
231	        tilingKey = GET_TPL_TILING_KEY(ELEMENTWISE_TPL_SCH_MODE_0);
232	        context->SetTilingKey(tilingKey);
